INSERT INTO Tickets (titulo, descripcion, id_estado, id_prioridad, fecha_creacion, fecha_limite, fecha_cierre, id_categoria, usuario_creador, tecnico_asignado) VALUES
('Permiso de solo lectura en el compartido de Calidad', 'Necesito acceso de solo lectura al compartido de Calidad para revisar los informes de auditoria interna.', 5, 4, '2026-09-08 11:47:00', '2026-09-08 15:47:00', '2026-09-08 14:32:00', 4, 2, 4),
('Firma corporativa desaparece de los mensajes', 'Desde esta semana los mensajes nuevos salen sin la firma corporativa aunque esta configurada en las opciones.', 3, 3, '2026-09-11 08:05:00', '2026-09-11 16:05:00', NULL, 5, 1, 4),
('El ventilador del equipo hace mucho ruido', 'Desde hace unos dias el ventilador del equipo emite un ruido fuerte y continuo que resulta molesto en la oficina.', 5, 2, '2026-10-01 09:12:00', '2026-10-02 09:12:00', '2026-10-02 17:39:00', 1, 2, 3),
('Sincronizacion de agenda con movil detenida', 'La agenda corporativa dejo de sincronizarse con el movil el lunes, sin cambios aparentes en la configuracion.', 4, 2, '2026-09-15 10:37:00', '2026-09-16 10:37:00', '2026-09-15 17:59:00', 2, 1, 3),
('Monitor con lineas verticales despues de un golpe', 'El monitor presenta tres lineas verticales permanentes desde que golpeo accidentalmente la pantalla al mover la mesa.', 5, 1, '2026-10-07 11:47:00', '2026-10-10 11:47:00', '2026-10-07 17:10:00', 1, 1, 3),
('Restaurar acceso tras la baja por vacaciones', 'Al volver de vacaciones el sistema no me deja entrar y me pide contactar con soporte para reactivar el perfil.', 2, 2, '2026-10-10 11:22:00', '2026-10-11 11:22:00', NULL, 4, 2, 4),
('Instalacion bloqueada por permisos en el equipo nuevo', 'En el equipo nuevo la instalacion del cliente corporativo se detiene por falta de permisos en la unidad C:.', 4, 3, '2026-10-10 09:07:00', '2026-10-10 17:07:00', '2026-10-11 12:41:00', 2, 1, 4),
('El programa de contabilidad pide activarse cada dia', 'Cada manana al abrir el programa de contabilidad vuelve a pedir la clave de activacion aunque se guardo ayer.', 1, 3, '2026-10-11 14:37:00', '2026-10-11 22:37:00', NULL, 2, 5, NULL),
('Cliente de facturacion cierra al imprimir', 'El cliente de facturacion se cierra de forma abrupta justo al enviar el documento a la impresora.', 5, 2, '2026-10-02 11:11:00', '2026-10-03 11:11:00', '2026-10-03 16:05:00', 2, 2, 4),
('Sin permisos para validar anticipos', 'Al intentar validar anticipos el sistema avisa de que mi perfil no tiene permisos suficientes para esa accion.', 3, 1, '2026-10-10 11:22:00', '2026-10-13 11:22:00', NULL, 4, 5, 3),
('No llegan los correos con adjuntos grandes', 'Los mensajes con adjuntos de mas de 10 MB no llegan al destinatario y no veo ningun aviso de error.', 4, 4, '2026-09-22 09:17:00', '2026-09-22 13:17:00', '2026-09-22 12:40:00', 5, 1, 4),
('Version antigua del navegador bloquea la intranet', 'La intranet muestra una pantalla de aviso de version no compatible porque el navegador no se actualiza solo.', 3, 1, '2026-10-09 08:23:00', '2026-10-12 08:23:00', NULL, 2, 1, 4),
('Errores al exportar informes a Excel', 'Al exportar cualquier informe a Excel el archivo se genera vacio o con las columnas desalineadas.', 4, 2, '2026-10-04 12:00:00', '2026-10-05 12:00:00', '2026-10-04 13:52:00', 2, 1, 3),
('Solicito acceso a la carpeta compartida de Nomina', 'Necesito acceso de lectura a la carpeta compartida de Nomina para poder consultar los justificantes del mes en curso.', 4, 2, '2026-10-09 11:25:00', '2026-10-10 11:25:00', '2026-10-09 16:01:00', 4, 1, 4),
('Portatil que se apaga solo al desconectar el cargador', 'El portatil se apaga instantaneamente al retirar el cargador aunque la bateria indique un 70 por ciento.', 5, 3, '2026-09-03 11:40:00', '2026-09-03 19:40:00', '2026-09-03 15:00:00', 1, 1, 4),
('Cambiar el correo vinculado a mi usuario', 'He cambiado de departamento y quiero recibir los avisos del sistema en el correo del nuevo equipo.', 1, 4, '2026-10-11 13:00:00', '2026-10-11 17:00:00', NULL, 4, 2, NULL),
('Perdida de paquetes en la conexion con la oficina', 'Durante las videollamadas con la sucursal se escuchan cortes y el informe de red muestra perdida de paquetes.', 4, 2, '2026-10-01 08:24:00', '2026-10-02 08:24:00', '2026-10-01 14:23:00', 3, 1, 4),
('Alta de usuario para la nueva becaria de marketing', 'Se ha incorporado una becaria al equipo de marketing y necesita cuenta de correo, acceso a la intranet y al compartido del departamento.', 1, 3, '2026-10-09 14:51:00', '2026-10-09 22:51:00', NULL, 4, 1, NULL),
('Falta una opcion de menu tras la migracion', 'Tras la migracion del sistema ya no aparece la opcion de menu de facturacion recurrente que se usaba a diario.', 2, 4, '2026-10-07 10:14:00', '2026-10-07 14:14:00', NULL, 2, 5, 4),
('No se abre la aplicacion de gestion tras la actualizacion', 'Despues de la ultima actualizacion la aplicacion de gestion cierra inmediatamente sin mostrar ningun mensaje de error.', 1, 1, '2026-10-09 10:25:00', '2026-10-12 10:25:00', NULL, 2, 1, NULL),
('Los equipos no ven la impresora de red', 'Ningun equipo de la zona norte encuentra la impresora de red en la lista, aunque ayer aparecia con normalidad.', 5, 3, '2026-09-12 10:32:00', '2026-09-12 18:32:00', '2026-09-12 17:06:00', 3, 5, 3),
('Outlook no sincroniza el correo desde ayer', 'El cliente de Outlook se queda cargando indefinidamente al intentar sincronizar la bandeja de entrada desde ayer por la tarde.', 4, 4, '2026-09-17 12:03:00', '2026-09-17 16:03:00', '2026-09-18 11:35:00', 5, 2, 4),
('Baja de acceso para colaborador externo', 'El colaborador externo dejo de trabajar con nosotros el viernes y hay que retirarle el acceso al portal de proyectos.', 5, 2, '2026-09-17 09:32:00', '2026-09-18 09:32:00', '2026-09-17 16:55:00', 4, 5, 4),
('Altavoz USB sin sonido en reuniones', 'El altavoz USB del salon de actos no emite sonido en las reuniones, aunque el sistema lo reconoce como dispositivo.', 4, 3, '2026-10-09 08:03:00', '2026-10-09 16:03:00', '2026-10-09 09:34:00', 1, 1, 4),
('Notificaciones de chat duplicadas en el movil', 'Cada mensaje de chat llega dos veces como notificacion en el movil del telefono corporativo.', 5, 1, '2026-09-08 14:26:00', '2026-09-11 14:26:00', '2026-09-08 17:46:00', 5, 1, 4),
('Outlook no sincroniza el correo desde ayer', 'El cliente de Outlook se queda cargando indefinidamente al intentar sincronizar la bandeja de entrada desde ayer por la tarde.', 3, 4, '2026-10-11 11:16:00', '2026-10-11 15:16:00', NULL, 5, 1, 4),
('Cuenta bloqueada tras varios intentos fallidos', 'Mi cuenta quedo bloqueada esta manana tras varios intentos fallidos de acceso y ahora no puedo iniciar sesion.', 2, 3, '2026-10-09 10:15:00', '2026-10-09 18:15:00', NULL, 4, 1, 4),
('Sincronizacion de agenda con movil detenida', 'La agenda corporativa dejo de sincronizarse con el movil el lunes, sin cambios aparentes en la configuracion.', 1, 3, '2026-10-09 11:04:00', '2026-10-09 19:04:00', NULL, 2, 1, NULL),
('Acceso lento al portal compartido por VPN', 'Abrir el portal tarda mas de un minuto solo cuando se accede desde fuera de la oficina mediante VPN.', 4, 2, '2026-09-11 11:56:00', '2026-09-12 11:56:00', '2026-09-12 08:51:00', 3, 2, 4),
('Raton inalambrico que se desconecta cada pocos minutos', 'El raton pierde la conexion de forma intermitente y hay que volver a emparejarlo cada pocos minutos.', 2, 3, '2026-10-10 08:38:00', '2026-10-10 16:38:00', NULL, 1, 1, 3),
('Falta el historial de conversaciones en el cliente', 'En el cliente de correo solo aparecen los mensajes del ultimo mes, el historial anterior no se carga.', 5, 3, '2026-10-01 08:28:00', '2026-10-01 16:28:00', '2026-10-01 11:15:00', 5, 1, 3),
('No se alcanza el servidor de archivos desde planta 3', 'Desde los equipos de la planta 3 no se abre el servidor de archivos, pero el resto de plantas conecta con normalidad.', 2, 1, '2026-10-10 14:52:00', '2026-10-13 14:52:00', NULL, 3, 1, 3),
('Escaner de la sala de juntas no alimenta papel', 'El escaner de la sala de juntas enciende pero no toma papel al intentar digitalizar documentos.', 4, 3, '2026-10-08 09:14:00', '2026-10-08 17:14:00', '2026-10-08 15:32:00', 1, 2, 3),
('La impresora de planta 2 no responde', 'La impresora compartida de la planta 2 aparece como desconectada para todos los usuarios de esa zona desde esta manana.', 4, 3, '2026-09-29 10:34:00', '2026-09-29 18:34:00', '2026-09-29 16:07:00', 1, 1, 4),
('Puerto bloqueado para la aplicion de consulta', 'La aplicion de consulta externa no conecta porque el puerto 8443 parece bloqueado en la pasarela.', 4, 3, '2026-09-09 12:49:00', '2026-09-09 20:49:00', '2026-09-10 12:09:00', 3, 2, 3),
('Falta una opcion de menu tras la migracion', 'Tras la migracion del sistema ya no aparece la opcion de menu de facturacion recurrente que se usaba a diario.', 5, 3, '2026-10-01 10:10:00', '2026-10-01 18:10:00', '2026-10-01 15:35:00', 2, 1, 3),
('Grabacion de llamadas no disponible en la sala 2', 'El boton de grabacion no aparece en la pantalla de la sala 2 aunque si funciona en las demas salas.', 1, 2, '2026-10-10 14:36:00', '2026-10-11 14:36:00', NULL, 5, 2, NULL),
('No puedo conectarme a la VPN desde casa', 'Al intentar iniciar el cliente VPN desde el portatil corporativo, la conexion falla con un error de autenticacion tras varios intentos.', 3, 2, '2026-10-09 08:05:00', '2026-10-10 08:05:00', NULL, 3, 2, 3),
('El ordenador no obtiene direccion IP automatica', 'Al enchufar el equipo a la red cableada no obtiene direccion IP y hay que configurarla a mano para conectar.', 1, 2, '2026-10-09 12:37:00', '2026-10-10 12:37:00', NULL, 3, 1, NULL),
('Firma corporativa desaparece de los mensajes', 'Desde esta semana los mensajes nuevos salen sin la firma corporativa aunque esta configurada en las opciones.', 1, 4, '2026-10-11 11:40:00', '2026-10-11 15:40:00', NULL, 5, 2, NULL),
('Portatil que se apaga solo al desconectar el cargador', 'El portatil se apaga instantaneamente al retirar el cargador aunque la bateria indique un 70 por ciento.', 2, 1, '2026-09-18 08:40:00', '2026-09-21 08:40:00', NULL, 1, 2, 3),
('Conexion a internet intermitente en la zona de recepcion', 'En recepcion la conexion a internet se corta cada pocos minutos y vuelve sola sin aviso previo.', 1, 3, '2026-10-11 16:17:00', '2026-10-12 00:17:00', NULL, 3, 2, NULL),
('Notificaciones de chat duplicadas en el movil', 'Cada mensaje de chat llega dos veces como notificacion en el movil del telefono corporativo.', 5, 2, '2026-09-16 11:59:00', '2026-09-17 11:59:00', '2026-09-17 10:06:00', 5, 2, 3),
('Alta de usuario para la nueva becaria de marketing', 'Se ha incorporado una becaria al equipo de marketing y necesita cuenta de correo, acceso a la intranet y al compartido del departamento.', 5, 2, '2026-10-01 09:28:00', '2026-10-02 09:28:00', '2026-10-01 15:00:00', 4, 1, 3),
('La Wi-Fi de la sala de reuniones se cae a menudo', 'La red inalambrica de la sala de reuniones se desconecta varias veces durante cada sesion.', 2, 2, '2026-10-11 09:16:00', '2026-10-12 09:16:00', NULL, 3, 1, 3),
('Correo rebotado hacia destinatarios externos', 'Los mensajes enviados a clientes externos rebotan con un aviso de politica de destinatarios.', 3, 3, '2026-10-09 12:35:00', '2026-10-09 20:35:00', NULL, 5, 2, 3),
('No puedo aceptar invitaciones de calendario', 'Al abrir una invitacion de reunion el boton de aceptar aparece desactivado y la reunion no se anade a mi agenda.', 2, 3, '2026-09-21 13:19:00', '2026-09-21 21:19:00', NULL, 5, 1, 3),
